import rules from '../../design-system/composition.rules.json';
/** Figma intended parents; slots expose only reviewed composition samples.
 * TagInput/TagMore belong to TagGroup, but have no editable JSON slot yet.
 * TagMore is generated by the renderer; TagInput composition remains unverified.
 */
export const slotRules: Record<string, Record<string, { component: string; min: number; max: number }>> = rules.slots;
export const allowedParents: Record<string, string[]> = rules.allowedParents;
export const internalComponents = new Set<string>(rules.internalComponents);
